# Inverted Ordering test:
# In IO, m3 ~ 0, m1 ~ 0.049 eV, m2 ~ 0.050 eV, sum = 0.0982 eV.
# If BOTH m1 and m2 decay at z_dec = 3.2:
def hubble_io_decay(z, h, omega_cb_h2, sum_m_nu=0.09823, z_dec=3.2):
    omega_nu_pre_h2 = sum_m_nu / 93.14
    omega_DR_0_h2 = omega_nu_pre_h2 / (1.0 + z_dec)

    Omega_cb_0 = omega_cb_h2 / (h**2)
    Omega_DR_0 = omega_DR_0_h2 / (h**2)
    Omega_Lambda = 1.0 - (Omega_cb_0 + Omega_DR_0)

    if z <= z_dec:
        rho_tot = Omega_cb_0 * ((1.0 + z)**3) + Omega_DR_0 * ((1.0 + z)**4) + Omega_Lambda
    else:
        Omega_nu_0 = omega_nu_pre_h2 / (h**2)
        rho_tot = (Omega_cb_0 + Omega_nu_0) * ((1.0 + z)**3) + Omega_Lambda
    return 100.0 * h * math.sqrt(rho_tot)

def comoving_distance_io_decay(z, h, omega_cb_h2, sum_m_nu=0.09823, z_dec=3.2):
    def inv_h(zp):
        return C_KM_S / hubble_io_decay(zp, h, omega_cb_h2, sum_m_nu, z_dec)
    return simpson_integral(inv_h, 0.0, z, n=1000)

def solve_h_io_decay(sum_m_nu=0.09823, z_dec=3.2):
    h_low, h_high = 0.55, 0.80
    for _ in range(50):
        h_mid = 0.5 * (h_low + h_high)
        d_mid = comoving_distance_io_decay(Z_STAR, h_mid, OMEGA_CB_H2, sum_m_nu, z_dec)
        if d_mid > d_star_target:
            h_low = h_mid
        else:
            h_high = h_mid
    return 0.5 * (h_low + h_high)

def compute_desi_chi2_io(sum_m_nu=0.09823, decay=False):
    if decay:
        h = solve_h_io_decay(sum_m_nu)
        dist_fn = lambda z: comoving_distance_io_decay(z, h, OMEGA_CB_H2, sum_m_nu)
        hub_fn = lambda z: hubble_io_decay(z, h, OMEGA_CB_H2, sum_m_nu)
    else:
        h = solve_h_for_neutrino_mass(sum_m_nu)
        dist_fn = lambda z: comoving_distance(z, h, OMEGA_CB_H2 + sum_m_nu / 93.14)
        omega_m = (OMEGA_CB_H2 + sum_m_nu / 93.14) / (h**2)
        hub_fn = lambda z: 100.0 * h * math.sqrt(omega_m * ((1.0 + z)**3) + (1.0 - omega_m))

    chi2 = 0.0
    for d in desi_data:
        z = d["z"]
        DM = dist_fn(z)
        DM_rd = DM / R_D
        Hz = hub_fn(z)
        DH_rd = (C_KM_S / Hz) / R_D
        pull_DM = (DM_rd - d["DM_rd"]) / d["sigma_DM"]
        pull_DH = (DH_rd - d["DH_rd"]) / d["sigma_DH"]
        chi2 += pull_DM**2 + pull_DH**2
    return 100.0 * h, chi2

h0_io_sta, chi2_io_sta = compute_desi_chi2_io(0.09823, decay=False)
h0_io_dec, chi2_io_dec = compute_desi_chi2_io(0.09823, decay=True)

print(f"IO Stable: H_0 = {h0_io_sta:.3f}, DESI BAO Chi2 = {chi2_io_sta:.2f}")
print(f"IO Decayed (z_dec=3.2): H_0 = {h0_io_dec:.3f}, DESI BAO Chi2 = {chi2_io_dec:.2f}")
print(f"Delta Chi2 (IO Decayed - Fiducial NO Stable): {chi2_io_dec - chi2_sta:+.2f}")

